//#region src/datamitsu-config/managed-configs/_yamlfmt_yaml.ts
const yamlfmtYaml = {
  content: (context) => {
    const data = YAML.parse(context.originalContent || "");
    const formatter = Object.fromEntries(
      Object.entries({
        ...data?.formatter,
        array_indent: indentSettings.indentWidth,
        eof_newline: true,
        force_array_style: "block",
        force_quote_style: "double",
        indent: indentSettings.indentWidth,
        line_ending: "lf",
        pad_line_comments: 1,
        retain_line_breaks_single: false,
        trim_trailing_whitespace: true,
        type: "basic",
      }).sort(([a], [b]) => a.localeCompare(b)),
    );
    return YAML.stringify(
      Object.fromEntries(
        Object.entries({
          ...data,
          exclude: yamlIgnore,
          formatter,
        }).sort(([a], [b]) => a.localeCompare(b)),
      ),
    );
  },
  otherFileNameList: [".yamlfmt", "yamlfmt.yml", "yamlfmt.yaml", ".yamlfmt.yml"],
  scope: "git-root",
  tools: ["yamlfmt"],
};
//#endregion
//#region src/datamitsu-config/managed-configs/_yamllint_yaml.ts
const yamllintYaml = {
  content: (context) => {
    const data = YAML.parse(context.originalContent || "");
    const rules = Object.fromEntries(
      Object.entries({
        ...data?.rules,
        comments: { "min-spaces-from-content": 1 },
        "comments-indentation": "enable",
        "document-end": "disable",
        "document-start": "disable",
        "empty-lines": { max: 1 },
        indentation: {
          "indent-sequences": true,
          spaces: indentSettings.indentWidth,
        },
        "key-ordering": "disable",
        "line-length": "disable",
        truthy: {
          "check-keys": false,
          level: "error",
        },
      }).sort(([a], [b]) => a.localeCompare(b)),
    );
    return YAML.stringify(
      Object.fromEntries(
        Object.entries({
          ...data,
          extends: "default",
          ignore: yamlIgnore.join("\n") + "\n",
          rules,
        }).sort(([a], [b]) => a.localeCompare(b)),
      ),
    );
  },
  otherFileNameList: [".yamllint", ".yamllint.yml"],
  scope: "git-root",
  tools: ["yamllint"],
};
